import { LB } from '@_core/_pagination';
import { Component, Input } from '@angular/core';

@Component({
  selector: 'tbl-col-template',
  standalone: false,
  templateUrl: './tbl-col-template.html',
  styles: `
    .cols-wrapper {
      display: flex;
      flex-wrap: nowrap;
      align-items: center;
      gap: 8px; /* optional spacing */
    }
  `,
  host: { class : 'col'}
})
export class TblColTemplate {
  @Input() lb: LB;
    get pageStart(): number {
    const pageNo = this.lb?.httpResPaginate?.pageNo ?? 1;
    const pageSize = this.lb?.httpResPaginate?.pageSize ?? 10;

    return ((pageNo - 1) * pageSize) + 1;
  }
}
